mapper.select:
SELECT  FROM prj.prj p LEFT JOIN mst.dev d ON d.dev_id=p.pm_dev_id
WHERE p.use_yn='Y'
  AND coalesce(p.prfm_bgn_dt,p.cntrct_bgn_dt) < make_date(#{year}+1,1,1)
  AND coalesce(p.cur_end_dt,p.cntrct_end_dt) >= make_date(#{year},1,1)
AND p.cntrct_ty_cd=#{type}
AND p.bsn_part_id=#{partId}
AND p.prj_stts_cd=#{status}
AND (p.prj_nm ILIKE '%' || #{q} || '%' OR p.prj_no ILIKE '%' || #{q} || '%')
ORDER BY p.prj_id

SELECT p.plan_ym AS month,sum(p.need_mm_qty) AS mm_qty FROM prj.psn_plan p
WHERE p.prj_id=#{id} AND p.plan_ym BETWEEN #{fromMonth} AND #{throughMonth}
GROUP BY p.plan_ym ORDER BY p.plan_ym

SELECT m.aloc_ym AS month,sum(m.aloc_amt)::bigint AS amount
FROM prj.tk_aloc_line l JOIN prj.tk_aloc_mth m ON m.aloc_line_id=l.aloc_line_id
WHERE l.prj_id=#{id} AND m.aloc_ym BETWEEN #{fromMonth} AND #{throughMonth}
  AND l.aloc_stg_cd=(SELECT s.aloc_stg_cd FROM prj.tk_aloc_line s WHERE s.prj_id=#{id}
    ORDER BY CASE s.aloc_stg_cd WHEN 'ACTUAL' THEN 0 WHEN 'FINAL' THEN 1 ELSE 2 END LIMIT 1)
GROUP BY m.aloc_ym ORDER BY m.aloc_ym
